mapper.update:
UPDATE document
SET deleted = 0,
    folder_id = #{FolderId}
WHERE id = #{documentId}

mapper.select:
SELECT name
FROM document
WHERE id = #{documentId}
AND space_id = #{spaceId}

SELECT EXISTS (
    SELECT 1 FROM document
    WHERE space_id = #{spaceId}
      AND folder_id = #{folderId}
      AND deleted = 0
      AND name = #{name}
)
